create schema if not exists private;

create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade,email text not null unique,display_name text,phone text,role text not null default 'crew' check(role in('admin','chief','assistant','crew')),must_set_password boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(lower(email) like '%@sdis76.fr'));
create table public.sectors (id uuid primary key default gen_random_uuid(),name text not null unique,description text,created_by uuid references public.profiles(user_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.sector_memberships (sector_id uuid not null references public.sectors(id) on delete cascade,user_id uuid not null references public.profiles(user_id) on delete cascade,sector_role text not null default 'crew' check(sector_role in('chief','assistant','crew')),is_primary boolean not null default false,created_at timestamptz not null default now(),primary key(sector_id,user_id));
create table public.beaches (id uuid primary key default gen_random_uuid(),sector_id uuid not null references public.sectors(id) on delete cascade,name text not null,location text,phone text,municipality_contact text,required_crew smallint not null default 2 check(required_crew between 1 and 3),promenade_places smallint not null default 1 check(promenade_places between 0 and 3),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(sector_id,name));
create table public.campaigns (id uuid primary key default gen_random_uuid(),sector_id uuid not null references public.sectors(id) on delete cascade,title text not null,starts_on date not null,ends_on date not null,deadline timestamptz not null,status text not null default 'draft' check(status in('draft','open','closed','published','archived')),created_by uuid not null references public.profiles(user_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_on>=starts_on));
create table public.availabilities (campaign_id uuid not null references public.campaigns(id) on delete cascade,user_id uuid not null references public.profiles(user_id) on delete cascade,available_on date not null,status text not null check(status in('available','preference','unavailable')),comment text check(char_length(comment)<=500),submitted_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(campaign_id,user_id,available_on));
create table public.assignments (id uuid primary key default gen_random_uuid(),beach_id uuid not null references public.beaches(id) on delete cascade,assigned_on date not null,user_id uuid not null references public.profiles(user_id) on delete cascade,position text not null check(position in('chief','crew','promenade')),published_at timestamptz,created_at timestamptz not null default now(),unique(assigned_on,user_id),unique(beach_id,assigned_on,user_id));
create table public.replacement_requests (id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,requester_id uuid not null references public.profiles(user_id) on delete cascade,proposed_replacement_id uuid references public.profiles(user_id),request_type text not null check(request_type in('direct_swap','open_search')),reason text check(char_length(reason)<=1000),status text not null default 'pending' check(status in('pending','approved','refused','cancelled')),decision_comment text check(char_length(decision_comment)<=1000),decided_by uuid references public.profiles(user_id),created_at timestamptz not null default now(),decided_at timestamptz);

create function private.current_app_role() returns text language sql stable security invoker set search_path='' as $$select coalesce(auth.jwt()->'app_metadata'->>'role','crew')$$;
revoke all on function private.current_app_role() from public;
grant usage on schema private to authenticated;
grant execute on function private.current_app_role() to authenticated;

create function private.prepare_auth_user() returns trigger language plpgsql security definer set search_path='' as $$declare assigned_role text;begin if new.email is null or lower(split_part(new.email,'@',2))<>'sdis76.fr' then raise exception 'Seules les adresses @sdis76.fr sont autorisées';end if;if exists(select 1 from auth.users) then assigned_role:='crew';else assigned_role:='admin';end if;new.raw_app_meta_data:=coalesce(new.raw_app_meta_data,'{}'::jsonb)||jsonb_build_object('role',assigned_role,'allowed_domain','sdis76.fr');return new;end$$;
create function private.create_profile_for_auth_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(user_id,email,role,must_set_password) values(new.id,lower(new.email),coalesce(new.raw_app_meta_data->>'role','crew'),true);return new;end$$;
revoke all on function private.prepare_auth_user() from public,anon,authenticated;
revoke all on function private.create_profile_for_auth_user() from public,anon,authenticated;
create trigger vigi_prepare_auth_user before insert on auth.users for each row execute function private.prepare_auth_user();
create trigger vigi_create_profile after insert on auth.users for each row execute function private.create_profile_for_auth_user();

create function public.touch_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$begin new.updated_at=now();return new;end$$;
create trigger profiles_touch_updated_at before update on public.profiles for each row execute function public.touch_updated_at();
create trigger sectors_touch_updated_at before update on public.sectors for each row execute function public.touch_updated_at();
create trigger beaches_touch_updated_at before update on public.beaches for each row execute function public.touch_updated_at();
create trigger campaigns_touch_updated_at before update on public.campaigns for each row execute function public.touch_updated_at();
create trigger availabilities_touch_updated_at before update on public.availabilities for each row execute function public.touch_updated_at();

alter table public.profiles enable row level security;alter table public.sectors enable row level security;alter table public.sector_memberships enable row level security;alter table public.beaches enable row level security;alter table public.campaigns enable row level security;alter table public.availabilities enable row level security;alter table public.assignments enable row level security;alter table public.replacement_requests enable row level security;

create policy profiles_select on public.profiles for select to authenticated using(user_id=(select auth.uid()) or (select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships mine join public.sector_memberships theirs on theirs.sector_id=mine.sector_id where mine.user_id=(select auth.uid()) and theirs.user_id=profiles.user_id));
create policy profiles_update_own on public.profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy sectors_select on public.sectors for select to authenticated using(true);
create policy sectors_admin_all on public.sectors for all to authenticated using((select private.current_app_role())='admin') with check((select private.current_app_role())='admin');
create policy memberships_select on public.sector_memberships for select to authenticated using(user_id=(select auth.uid()) or (select private.current_app_role())='admin');
create policy memberships_admin_all on public.sector_memberships for all to authenticated using((select private.current_app_role())='admin') with check((select private.current_app_role())='admin');
create policy beaches_select on public.beaches for select to authenticated using(true);
create policy beaches_manage on public.beaches for all to authenticated using((select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships m where m.sector_id=beaches.sector_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant'))) with check((select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships m where m.sector_id=beaches.sector_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant')));
create policy campaigns_select on public.campaigns for select to authenticated using((select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships m where m.sector_id=campaigns.sector_id and m.user_id=(select auth.uid())));
create policy campaigns_manage on public.campaigns for all to authenticated using((select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships m where m.sector_id=campaigns.sector_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant'))) with check((select private.current_app_role())='admin' or exists(select 1 from public.sector_memberships m where m.sector_id=campaigns.sector_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant')));
create policy availability_select on public.availabilities for select to authenticated using(user_id=(select auth.uid()) or (select private.current_app_role())='admin' or exists(select 1 from public.campaigns c join public.sector_memberships m on m.sector_id=c.sector_id where c.id=availabilities.campaign_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant')));
create policy availability_insert_own on public.availabilities for insert to authenticated with check(user_id=(select auth.uid()));
create policy availability_update_own on public.availabilities for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy availability_delete_own on public.availabilities for delete to authenticated using(user_id=(select auth.uid()));
create policy assignments_select on public.assignments for select to authenticated using(user_id=(select auth.uid()) or (select private.current_app_role())='admin' or exists(select 1 from public.beaches b join public.sector_memberships m on m.sector_id=b.sector_id where b.id=assignments.beach_id and m.user_id=(select auth.uid())));
create policy assignments_manage on public.assignments for all to authenticated using((select private.current_app_role())='admin' or exists(select 1 from public.beaches b join public.sector_memberships m on m.sector_id=b.sector_id where b.id=assignments.beach_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant'))) with check((select private.current_app_role())='admin' or exists(select 1 from public.beaches b join public.sector_memberships m on m.sector_id=b.sector_id where b.id=assignments.beach_id and m.user_id=(select auth.uid()) and m.sector_role in('chief','assistant')));
create policy replacements_select on public.replacement_requests for select to authenticated using(requester_id=(select auth.uid()) or proposed_replacement_id=(select auth.uid()) or (select private.current_app_role())='admin');
create policy replacements_insert_own on public.replacement_requests for insert to authenticated with check(requester_id=(select auth.uid()));
create policy replacements_update_own_pending on public.replacement_requests for update to authenticated using(requester_id=(select auth.uid()) and status='pending') with check(requester_id=(select auth.uid()));
create policy replacements_admin_update on public.replacement_requests for update to authenticated using((select private.current_app_role())='admin') with check((select private.current_app_role())='admin');

revoke all on all tables in schema public from anon;
grant select on public.profiles,public.sectors,public.sector_memberships,public.beaches,public.campaigns,public.availabilities,public.assignments,public.replacement_requests to authenticated;
grant update(display_name,phone,must_set_password) on public.profiles to authenticated;
grant insert,update,delete on public.sectors,public.sector_memberships,public.beaches,public.campaigns,public.assignments to authenticated;
grant insert,update,delete on public.availabilities,public.replacement_requests to authenticated;
